add_action( 'woocommerce_email_after_order_table', 'perfectpixel_related_products_in_emails', 20, 4 );

function perfectpixel_related_products_in_emails( $order, $sent_to_admin, $plain_text, $email ) {
	if ( $sent_to_admin || $plain_text || ! $email || ! in_array( $email->id, array( 'customer_processing_order', 'customer_completed_order' ), true ) ) {
		return;
	}
	$bought = array();
	$ids    = array();
	foreach ( $order->get_items() as $item ) {
		$bought[] = (int) $item->get_product_id();
		$product  = wc_get_product( $item->get_product_id() );
		if ( $product ) {
			$ids = array_merge( $ids, $product->get_cross_sell_ids(), wc_get_related_products( $product->get_id(), 6 ) );
		}
	}
	$ids = array_slice( array_values( array_diff( array_unique( array_map( 'intval', $ids ) ), $bought ) ), 0, max( 1, (int) '{{email_products_count}}' ) );
	if ( ! $ids ) {
		return;
	}
	$width = floor( 100 / count( $ids ) );
	echo '<h2>' . esc_html( '{{email_products_heading}}' ) . '</h2><table cellspacing="0" cellpadding="6" border="0" style="width:100%;margin-bottom:40px"><tr>';
	foreach ( $ids as $id ) {
		$product = wc_get_product( $id );
		if ( ! $product || ! $product->is_visible() ) {
			continue;
		}
		$image = wp_get_attachment_image_url( $product->get_image_id(), 'woocommerce_thumbnail' );
		printf(
			'<td valign="top" align="center" style="width:%1$d%%"><a href="%2$s" style="text-decoration:none">%3$s<br><strong>%4$s</strong></a><br>%5$s</td>',
			(int) $width,
			esc_url( $product->get_permalink() ),
			$image ? '<img src="' . esc_url( $image ) . '" alt="" width="150" style="max-width:100%;height:auto;margin-bottom:6px">' : '',
			esc_html( $product->get_name() ),
			wp_kses_post( $product->get_price_html() )
		);
	}
	echo '</tr></table>';
}
